// app/[username]/opengraph-image.tsx - Social share image for a public card
//
// Snap compliance: the Bitmoji avatar is shown UNMODIFIED — no filters, no
// recolouring, no overlays on the art. It is placed on a plain dark
// background and nothing is drawn on top of it.
//
// The image is generated by next/og (Satori) and cached by the framework.
import { ImageResponse } from 'next/og'
import { readFile } from 'node:fs/promises'
import { join } from 'node:path'

import { createAdminClient } from '@/lib/supabase/admin'
import { getBitmojiPoseUrl } from '@/lib/snap/bitmoji'

export const alt = 'Xlay card'
export const size = { width: 1200, height: 630 }
export const contentType = 'image/png'

// Read the fonts once at module scope — they do not depend on request data.
const syneBold = readFile(join(process.cwd(), 'assets/fonts/Syne-800.ttf'))
const syneRegular = readFile(join(process.cwd(), 'assets/fonts/Syne-700.ttf'))
const dmSans = readFile(join(process.cwd(), 'assets/fonts/DMSans-500.ttf'))
const dmSansRegular = readFile(join(process.cwd(), 'assets/fonts/DMSans-400.ttf'))

const ACCENT = '#E8FF47'
const BASE_BG = '#080808'

// Cache the generated image for an hour so repeat shares are cheap.
export const revalidate = 3600

export default async function Image({
  params,
}: {
  params: Promise<{ username: string }>
}) {
  const { username } = await params

  let displayName = 'Xlay'
  let handle = username
  let bio: string | null = null
  let avatarUrl: string | null = null
  let avatarPose: string | null = null
  let isPrivate = false

  try {
    const admin = createAdminClient()
    const { data } = await admin
      .from('profiles')
      .select('display_name, bio, avatar_url, avatar_pose, is_private')
      .eq('username', username.toLowerCase())
      .maybeSingle()

    if (data) {
      displayName = data.display_name
      bio = data.bio
      avatarUrl = data.avatar_url
      avatarPose = data.avatar_pose
      isPrivate = data.is_private
    }
  } catch {
    // Fall back to the generic card rather than failing the image.
  }

  // Private cards get a generic image with no personal data.
  if (isPrivate) {
    displayName = 'Xlay'
    handle = 'xlay.me'
    bio = null
    avatarUrl = null
  }

  // Bitmoji art is rendered unmodified by the Snap SDK.
  const imageSrc = avatarUrl ? getBitmojiPoseUrl(avatarUrl, avatarPose) : null

  return new ImageResponse(
    (
      <div
        style={{
          width: '100%',
          height: '100%',
          display: 'flex',
          background: BASE_BG,
          color: '#f5f5f5',
          fontFamily: 'DM Sans',
          position: 'relative',
        }}
      >
        {/* Accent bar — decorative, behind all content */}
        <div
          style={{
            position: 'absolute',
            left: 0,
            top: 0,
            width: 12,
            height: '100%',
            background: ACCENT,
          }}
        />

        {/* Centred content column */}
        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            flex: 1,
            padding: '60px 100px',
            gap: 24,
            textAlign: 'center',
          }}
        >
          {/* Avatar — shown unmodified */}
          {imageSrc ? (
            <img
              src={imageSrc}
              width={150}
              height={200}
              style={{ objectFit: 'contain' }}
            />
          ) : null}

          {/* Name + handle */}
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              gap: 10,
              alignItems: 'center',
            }}
          >
            <div
              style={{
                fontFamily: 'Syne',
                fontSize: 64,
                fontWeight: 800,
                lineHeight: 1.05,
                display: 'flex',
                textAlign: 'center',
              }}
            >
              {displayName}
            </div>
            <div style={{ fontSize: 32, color: '#a1a1aa', display: 'flex' }}>
              @{handle}
            </div>
          </div>

          {/* Bio */}
          {bio ? (
            <div
              style={{
                fontSize: 26,
                color: '#a1a1aa',
                maxWidth: 800,
                display: 'flex',
                textAlign: 'center',
                lineHeight: 1.4,
              }}
            >
              {bio.length > 120 ? `${bio.slice(0, 120)}…` : bio}
            </div>
          ) : null}

          {/* Wordmark */}
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 14,
              marginTop: 8,
            }}
          >
            <div
              style={{
                fontFamily: 'Syne',
                fontSize: 32,
                fontWeight: 700,
                color: ACCENT,
                display: 'flex',
              }}
            >
              Xlay
            </div>
            <div style={{ fontSize: 24, color: '#71717a', display: 'flex' }}>
              Show Up.
            </div>
          </div>
        </div>
      </div>
    ),
    {
      ...size,
      fonts: [
        { name: 'Syne', data: await syneBold, style: 'normal', weight: 800 },
        { name: 'Syne', data: await syneRegular, style: 'normal', weight: 700 },
        { name: 'DM Sans', data: await dmSans, style: 'normal', weight: 500 },
        { name: 'DM Sans', data: await dmSansRegular, style: 'normal', weight: 400 },
      ],
    }
  )
}
